/**
 *
 * DataTableColumnResizer provides a draggable handle for resizing DataTable columns.
 *
 * [Live Demo](https://www.primereact.org/datatable/)
 *
 * @module DataTableColumnResizer
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { UseDataTableColumnResizeEvent } from '@primereact/types/headless/datatable';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { DataTableRootInstance } from './DataTableRoot.types';
/**
 * Defines passthrough(pt) options type in DataTableColumnResizer component.
 */
export type DataTableColumnResizerPassThroughType<E> = PassThroughType<DataTableColumnResizerInstance, E>;
/**
 * Defines passthrough(pt) options of DataTableColumnResizer component.
 */
export interface DataTableColumnResizerPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: DataTableColumnResizerPassThroughType<React.HTMLAttributes<HTMLSpanElement>>;
}
/**
 * Defines valid properties in DataTableColumnResizer component.
 */
export interface DataTableColumnResizerProps extends BaseComponentProps<DataTableColumnResizerInstance, unknown, DataTableColumnResizerPassThrough, 'span'> {
    /**
     * Index of the column to resize. When omitted, it is derived from the parent `<th>` `cellIndex`.
     */
    columnIndex?: number;
}
/**
 * Defines valid state in DataTableColumnResizer component.
 */
export interface DataTableColumnResizerState {
}
/**
 * Defines the methods and properties exposed by DataTableColumnResizer component.
 */
export interface DataTableColumnResizerExposes {
    /**
     * The DataTable component instance.
     */
    datatable: DataTableRootInstance | undefined | null;
}
/**
 * Instance of DataTableColumnResizer component.
 */
export type DataTableColumnResizerInstance = ComponentInstance<DataTableColumnResizerProps, DataTableColumnResizerState, DataTableColumnResizerExposes>;
/**
 * Event re-exported from the headless layer so consumers can import it from the
 * primitive/UI barrel instead of reaching into headless. Mirrors `UseDataTableColumnResizeEvent`.
 */
export interface DataTableColumnResizeEvent extends UseDataTableColumnResizeEvent {
}
